from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')

start_marker = 'function openKaspiAdsImport()'
end_marker = 'function removeKaspiAdsBatch('
if s.count(start_marker) != 1 or s.count(end_marker) != 1:
    raise SystemExit('Kaspi ads import markers changed; refusing unsafe patch')

start = s.index(start_marker)
end = s.index(end_marker, start)

new = r'''function openKaspiAdsImport(){const today=localDateInputValue();showSheet(`<h3>Реклама Kaspi · по товарам</h3><div class="link-note"><b>Загрузите «Отчёт по товарам» Kaspi.</b> Расход берётся прямо из колонки «Расходы на рекламу» каждой строки и относится к товару из колонки «Рекламируемый товар». Для CSV десятичная запятая сохраняется как копейки тенге: 164,69 = 164.69 ₸.</div><div class="two"><div class="field"><label>Дата от</label><input id="kaspiAdsFrom" type="date" value="${today}"></div><div class="field"><label>Дата до</label><input id="kaspiAdsTo" type="date" value="${today}"></div></div><div class="field"><label>Отчёт по товарам Kaspi (Excel/CSV)</label><input id="kaspiAdsFile" type="file" accept=".xlsx,.xls,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,text/csv"></div><div class="link-note">Если в файле нет отдельной колонки «Дата», импортируйте один день за раз и укажите одинаковые даты «от» и «до». Общая сумма между товарами не распределяется.</div><button class="btn dark full" onclick="importKaspiAdsFile()">Импортировать расходы по товарам</button>`)}
async function kaspiAdsHash(buffer){try{if(!crypto?.subtle)return '';const digest=await crypto.subtle.digest('SHA-256',buffer.slice(0));return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch{return ''}}
async function kaspiAdsTextHash(text){try{const data=new TextEncoder().encode(String(text||''));return await kaspiAdsHash(data.buffer)}catch{return ''}}
function kaspiAdsParseDelimitedText(text){const src=String(text??'').replace(/^\uFEFF/,''),first=(src.match(/^[^\r\n]*/)||[''])[0],semis=(first.match(/;/g)||[]).length,commas=(first.match(/,/g)||[]).length,delimiter=semis>=commas?';':',';const grid=[];let row=[],cell='',quoted=false;for(let i=0;i<src.length;i++){const ch=src[i];if(quoted){if(ch==='"'){if(src[i+1]==='"'){cell+='"';i++}else quoted=false}else cell+=ch;continue}if(ch==='"'){quoted=true;continue}if(ch===delimiter){row.push(cell);cell='';continue}if(ch==='\n'){row.push(cell.replace(/\r$/,''));grid.push(row);row=[];cell='';continue}cell+=ch}if(cell.length||row.length){row.push(cell.replace(/\r$/,''));grid.push(row)}while(grid.length&&!grid[0].some(v=>String(v??'').trim()))grid.shift();const headers=(grid.shift()||[]).map((x,i)=>String(x??'').trim()||`column_${i+1}`);return grid.filter(r=>r.some(v=>String(v??'').trim())).map(r=>{const o={};headers.forEach((h,i)=>o[h]=r[i]??'');return o})}
async function kaspiAdsParseFile(file,XLSX){const buffer=await file.arrayBuffer();let rows=[];if(/\.csv$/i.test(String(file.name||''))||/csv/i.test(String(file.type||''))){rows=kaspiAdsParseDelimitedText(new TextDecoder('utf-8').decode(buffer))}else{const workbook=XLSX.read(buffer,{type:'array',cellDates:true}),sheet=workbook.Sheets[workbook.SheetNames[0]];rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:true})}if(!rows.length)throw new Error(`В файле «${file.name}» нет строк`);const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))],normalized=headers.map(k=>[k,adsColumn(k)]);return {buffer,rows,headers,normalized}}
async function importKaspiAdsFile(){const input=document.getElementById('kaspiAdsFile'),file=input?.files?.[0],fromDate=document.getElementById('kaspiAdsFrom')?.value||'',toDate=document.getElementById('kaspiAdsTo')?.value||'';if(!file)return alert('Выберите «Отчёт по товарам» Kaspi');const a=orderDayStart(fromDate),b=orderDayStart(toDate);if(a===null||b===null)return alert('Укажите дату отчёта');const fallbackFrom=a<=b?fromDate:toDate,fallbackTo=a<=b?toDate:fromDate;try{const XLSX=await loadXlsxLibrary(),parsed=await kaspiAdsParseFile(file,XLSX),rows=parsed.rows,headers=parsed.headers,normalized=parsed.normalized,adCostKey=(normalized.find(([,n])=>/^расход.*реклам$|^реклам.*расход$|затрат.*реклам|реклам.*затрат|стоимост.*реклам/.test(n)))?.[0]||'',costKey=adCostKey||(normalized.find(([,n])=>n==='стоимость')||normalized.find(([,n])=>/^стоимость\b/.test(n)))?.[0];if(!costKey)throw new Error('Не найден столбец «Расходы на рекламу». Нужен «Отчёт по товарам» Kaspi.');const skuKey=(normalized.find(([,n])=>n==='рекламируемый товар'||n==='sku'||n==='артикул')||normalized.find(([,n])=>/рекламируем.*товар|\bsku\b|артикул|код товара/.test(n)))?.[0]||'',nameKey=(normalized.find(([,n])=>n==='товар'||/^наименование товара$|^название товара$/.test(n))||normalized.find(([,n])=>/наименован.*товар|назван.*товар/.test(n)))?.[0]||'',dateKey=(normalized.find(([,n])=>n==='дата')||normalized.find(([,n])=>/^дата\b|^день\b|^date\b/.test(n)))?.[0]||'',campaignKey=(normalized.find(([,n])=>/кампан/.test(n)))?.[0]||'';if(!skuKey&&!nameKey)throw new Error('В «Отчёте по товарам» нет колонки «Рекламируемый товар», SKU/артикула или названия товара.');if(!dateKey&&fallbackFrom!==fallbackTo)throw new Error('В отчёте нет даты по строкам. Для такого CSV импортируйте один день за раз и укажите одинаковые даты «от» и «до».');const sourceKey=kaspiAdsSourceKey(file.name),detail=[];let unidentified=0,used=0;for(const row of rows){const rowText=headers.map(k=>String(row[k]??'')).join(' ').trim();if(/(^|\s)(итого|всего|total)(\s|$)/i.test(rowText))continue;const amount=adsMoney(row[costKey]);if(!(amount>0))continue;const sku=skuKey?String(row[skuKey]??'').trim():'',name=nameKey?String(row[nameKey]??'').trim():'',campaign=campaignKey?String(row[campaignKey]??'').trim():'';if(!sku&&!name){unidentified+=amount;continue}let date=dateKey?kaspiAdsIsoDate(row[dateKey]):'';if(!date){if(fallbackFrom===fallbackTo)date=fallbackFrom;else throw new Error('Есть строки расхода без корректной даты. Импортируйте отчёт за один день.')}const p=kaspiAdsMatchProduct({sku,name});detail.push({date,productId:p?.id||null,sku,name:p?.name||name,campaign,source:campaign||sourceKey,amount});used++}if(unidentified>0)throw new Error(`Есть рекламный расход ${fmt(unidentified)} без товара/SKU. Такой файл нельзя надёжно привязать.`);if(!detail.length)throw new Error('Не найдено строк с рекламным расходом по товарам');const grouped=new Map();for(const line of detail){const key=[line.date,line.source,String(line.sku||'').toLowerCase(),normalizeName(line.name),String(line.productId||'')].join('|');const old=grouped.get(key);if(old)old.amount+=line.amount;else grouped.set(key,{...line})}const lines=[...grouped.values()].sort((x,y)=>String(x.date).localeCompare(String(y.date))||String(x.source).localeCompare(String(y.source))||String(x.sku).localeCompare(String(y.sku))||String(x.name).localeCompare(String(y.name))),total=lines.reduce((n,x)=>n+(Number(x.amount)||0),0),dates=lines.map(x=>x.date).filter(Boolean).sort(),actualFrom=dates[0]||fallbackFrom,actualTo=dates[dates.length-1]||fallbackTo,canonical=lines.map(x=>[x.date,x.source,String(x.sku||'').trim().toLowerCase(),normalizeName(x.name),Math.round((Number(x.amount)||0)*100)/100]),detailHash=await kaspiAdsTextHash(JSON.stringify(canonical)),hash=await kaspiAdsHash(parsed.buffer);if((state.kaspiAdExpenses||[]).some(x=>(detailHash&&x.detailHash===detailHash)||(hash&&x.hash===hash&&x.parserVersion==='kaspi-product-csv-v2')))return alert('Этот корректно разобранный отчёт уже импортирован. Повторный импорт заблокирован.');const perProductMap=new Map();let unmatchedAmount=0;for(const line of lines){const p=kaspiAdsMatchProduct(line);if(p){line.productId=p.id;const old=perProductMap.get(p.id)||{productId:p.id,sku:line.sku,name:p.name,amount:0};old.amount+=line.amount;perProductMap.set(p.id,old)}else unmatchedAmount+=line.amount}const batch={id:'ads-'+id(),market:'Kaspi',source:'Kaspi Marketing product report',sourceKey,fileName:file.name,hash,detailHash,costColumn:costKey,parserVersion:'kaspi-product-csv-v2',fromDate:actualFrom,toDate:actualTo,amount:total,rowsCount:used,lines,perProduct:[...perProductMap.values()],unmatchedAmount,importedAt:Date.now()};state.kaspiAdExpenses.push(batch);save();closeModal();renderReports();alert(`Реклама Kaspi импортирована.\nПериод: ${actualFrom} — ${actualTo}\nРасход: ${fmt(total)}\nКолонка расходов: ${costKey}\nСтрок с расходом: ${lines.length}\nПривязано: ${fmt(total-unmatchedAmount)}${unmatchedAmount>0?'\nБез привязки: '+fmt(unmatchedAmount):''}`)}catch(e){alert('Не удалось импортировать рекламу Kaspi:\n'+String(e.message||e))}}
'''

s = s[:start] + new + s[end:]
p.write_text(s, encoding='utf-8')
